        onClick?.(event);
        if (
          root &&
          !event.baseUIHandlerPrevented &&
          event.detail > 0 &&
          event.currentTarget.getAttribute('aria-expanded') === 'true' &&
          root.justSwitched()
        ) {
          event.preventBaseUIHandler();
          root.keptOpen();
        }
      }}
    />
  );
