function Control({ onPointerDownCapture, ...props }: Control.Props) {
  const { startPress } = useSliderMotion();

  return (
    <SliderPrimitive.Control
      {...props}
      onPointerDownCapture={(event) => {
        onPointerDownCapture?.(event);
        startPress(event);
      }}
    />
